  let boundM=null;
  function bindMvu(){const m=M();if(!m||boundM===m)return;boundM=m;for(const name of ['VARIABLE_UPDATE_ENDED','BEFORE_MESSAGE_UPDATE'])listen(m.events?.[name],()=>schedule(250));}
