  observer=new host.MutationObserver(records=>{if(records.some(r=>!r.target?.closest?.('.wnq-dialogue-mount')&&(r.target?.closest?.('#chat')||r.target===doc.querySelector('#chat'))))schedule(220);});observer.observe(doc.body,{childList:true,subtree:true});
